"use client";

import { cn } from "@/lib/utils";
import type { Variants } from "motion/react";
import {
 LazyMotion,
 domMin,
 m,
 useAnimation,
 useReducedMotion,
} from "motion/react";
import {
 forwardRef,
 useCallback,
 useImperativeHandle,
 useRef,
 type HTMLAttributes,
} from "react";
export interface BatteryFullIconHandle {
 startAnimation: () => void;
 stopAnimation: () => void;
}

interface BatteryFullIconProps extends Omit<
 HTMLAttributes<HTMLDivElement>,
 | "color"
 | "onDrag"
 | "onDragStart"
 | "onDragEnd"
 | "onAnimationStart"
 | "onAnimationEnd"
 | "onAnimationIteration"
> {
 size?: number;
 duration?: number;
 isAnimated?: boolean;
 color?: string;
}

const BatteryFullIcon = forwardRef<BatteryFullIconHandle, BatteryFullIconProps>(
 (
  {
   onMouseEnter,
   onMouseLeave,
   className,
   size = 24,
   duration = 1,
   isAnimated = true,
   color,
   ...props
  },
  ref,
 ) => {
  const controls = useAnimation();
  const reduced = useReducedMotion();
  const isControlled = useRef(false);

  useImperativeHandle(ref, () => {
   isControlled.current = true;
   return {
    startAnimation: () =>
     reduced ? controls.start("normal") : controls.start("animate"),
    stopAnimation: () => controls.start("normal"),
   };
  });

  const handleEnter = useCallback(
   (e?: React.MouseEvent<HTMLDivElement>) => {
    if (!isAnimated || reduced) return;
    if (!isControlled.current) controls.start("animate");
    else onMouseEnter?.(e as any);
   },
   [controls, reduced, isAnimated, onMouseEnter],
  );

  const handleLeave = useCallback(
   (e?: React.MouseEvent<HTMLDivElement>) => {
    if (!isControlled.current) controls.start("normal");
    else onMouseLeave?.(e as any);
   },
   [controls, onMouseLeave],
  );

  const levelVariants = (delay: number): Variants => ({
   normal: { scaleY: 1 },
   animate: {
    scaleY: [1, 0.35, 1],
    transition: {
     duration: 0.4 * duration,
     ease: "easeInOut",
     delay: delay * duration,
    },
   },
  });

  const nubVariants: Variants = {
   normal: { scaleY: 1 },
   animate: {
    scaleY: [1, 1.6, 1],
    transition: {
     duration: 0.4 * duration,
     ease: "easeInOut",
     delay: 0.35 * duration,
    },
   },
  };

  return (
   <LazyMotion features={domMin} strict>
    <m.div
     className={cn("inline-flex items-center justify-center", className)}
     onMouseEnter={handleEnter}
     onMouseLeave={handleLeave}
     {...props}
     style={{ color, ...props.style }}
    >
     <m.svg
      xmlns="http://www.w3.org/2000/svg"
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="2"
      strokeLinecap="round"
      strokeLinejoin="round"
      animate={controls}
      initial="normal"
     >
      <m.path
       d="M6 10v4"
       variants={levelVariants(0)}
       style={{ transformBox: "view-box", originX: "6px", originY: "12px" }}
      />
      <m.path
       d="M10 10v4"
       variants={levelVariants(0.12)}
       style={{ transformBox: "view-box", originX: "10px", originY: "12px" }}
      />
      <m.path
       d="M14 10v4"
       variants={levelVariants(0.24)}
       style={{ transformBox: "view-box", originX: "14px", originY: "12px" }}
      />
      <m.path
       d="M22 14v-4"
       variants={nubVariants}
       style={{ transformBox: "view-box", originX: "22px", originY: "12px" }}
      />
      <rect x="2" y="6" width="16" height="12" rx="2" />
     </m.svg>
    </m.div>
   </LazyMotion>
  );
 },
);

BatteryFullIcon.displayName = "BatteryFullIcon";
export { BatteryFullIcon };
